<?php require_once __DIR__.'/../../config/app.php';requireLogin();$pageTitle='Supplier';$pageSubtitle='Data Supplier koperasi sekolah';$isAdmin=(authUser()['role']==='admin');$success=flash('success');$stmt=$pdo->query('SELECT * FROM suppliers ORDER BY supplier_id DESC');$rows=$stmt->fetchAll(); ?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Supplier - Koperasi Sekolah</title><link rel="stylesheet" href="/styles/suppliers/index.css"></head><body><div class="layout"><?php require __DIR__.'/../../components/admin/sidebar.php';?><main class="main"><?php require __DIR__.'/../../components/admin/topbar.php';?><section class="content"><div class="toolbar"><div class="page-heading"><h2>Data Supplier</h2><p>Daftar supplier koperasi sekolah.</p></div><?php if($isAdmin):?><a class="btn btn-primary" href="create.php">+ Tambah Supplier</a><?php endif?></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif?><div class="card"><table><thead><tr><th>Nama Supplier</th><th>Email</th><th>Telepon</th><th>Alamat</th><th>Jenis Produk</th><th>Tanggal Partnership</th><?php if($isAdmin):?><th>Aksi</th><?php endif?></tr></thead><tbody><?php if(!$rows):?><tr><td class="empty" colspan="7">Belum ada data supplier.</td></tr><?php else:foreach($rows as $row):?><tr><td><?= e($row['supplier_name']) ?></td><td><?= e($row['email']) ?></td><td><?= e($row['phone']) ?></td><td><?= e($row['address']) ?></td><td><?= e(implode(', ', json_decode($row['product_types'] ?: '[]', true) ?: [])) ?></td><td><?= e($row['partnership_date']) ?></td><?php if($isAdmin):?><td class="actions"><a href="edit.php?id=<?= (int)$row['supplier_id'] ?>">Edit</a><a class="delete" href="/actions/suppliers/destroy.php?id=<?= (int)$row['supplier_id'] ?>" onclick="return confirm('Yakin ingin menghapus data ini?')">Hapus</a></td><?php endif?></tr><?php endforeach;endif?></tbody></table></div></section></main></div></body></html>